<?php
	$url = "https://businesscard.lightmatrix3d.com/";
	$id = isset($_GET["id"]) ? $_GET["id"] : "";
	if(empty($id)) {
		header("Location: " . $url . "company/");
		exit();
	}
	$GLOBALS["server"] = true;
	$name = "3D名片";
	$icon = $url . "lightmatrix.png";
	$infoIP = "https://lm3d.s3.ap-northeast-1.amazonaws.com/businesscard/";//info.json的網址
	$cardMessage = "";
	//是否是新模式
	if($isNewMode = strlen($id) >= 20) {
		// 要发送的数据
		$data = array(
			'public_id' => isset($_GET['id']) ? $_GET['id'] : ''
		);
		$jsonData = json_encode($data);
		// 初始化 cURL 会话
		$ch = curl_init($url . "api/getBC_info");
		// 设置 cURL 选项
		curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
		curl_setopt($ch, CURLOPT_POST, true);
		curl_setopt($ch, CURLOPT_POSTFIELDS, $jsonData);
		curl_setopt($ch, CURLOPT_HTTPHEADER, array(
			'Content-Type: application/json',
			'Content-Length: ' . strlen($jsonData)
		));
		// 设置超时时间
		curl_setopt($ch, CURLOPT_TIMEOUT, 30); // 请求最大执行时间
		curl_setopt($ch, CURLOPT_CONNECTTIMEOUT, 30); // 连接最大时间
		// 执行 cURL 请求并获取响应
		$response = curl_exec($ch);
		// 检查是否有错误
		if ($response !== false) {
			// 解析并处理响应
			$responseData = json_decode($response, true);
			if(isset($responseData))
				if(isset($responseData["success"]) && $responseData["success"] && isset($responseData["message"])) {
					$message = $responseData["message"];
					if(isset($message["release_name"]) && !empty($message["release_name"]))
						$name = $message["release_name"];
					if(isset($message["model"]) && isset($message["model"]["cover_half"]) && !empty($message["model"]["cover_half"]))
						$icon = $message["model"]["cover_half"];
					$cardMessage = json_encode($message, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
				}
		}
		// 关闭 cURL 会话
		curl_close($ch);
	} else {
		//舊模式
		function removeBOM($string) {
			if (substr($string, 0, 3) == "\xEF\xBB\xBF") {
				$string = substr($string, 3);
			}
			return $string;
		}
		//資訊
		$ch = curl_init($infoIP . $id . "/info.json");
		curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
		curl_setopt($ch, CURLOPT_HTTPHEADER, array(
			'Content-Type: application/json'
		));
		curl_setopt($ch, CURLOPT_TIMEOUT, 30); // 请求最大执行时间
		curl_setopt($ch, CURLOPT_CONNECTTIMEOUT, 30); // 连接最大时间
		$response = curl_exec($ch);
		if ($response !== false) {
			$response = removeBOM($response);
			$message = json_decode($response, true);
			if (json_last_error() === JSON_ERROR_NONE) {
				if(isset($message["name"]) && !empty($message["name"]))
					$name = $message["name"];
				$cardMessage = json_encode($message, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
			}
		}
		curl_close($ch);
		//縮圖
		$iconUrl = $infoIP . $id . "/icon.png";
		$headers = @get_headers($iconUrl);
		if ($headers && strpos($headers[0], '200'))
			$icon = $iconUrl;
		//echo "<!--" . $cardMessage . "-->";	
	}
	//讀取js
	function import($path) {
		if($GLOBALS["server"]) return '<script src="' . asset('js/' . $path) . '"></script>';
		return '<script src="' .  $path . '"></script>';
	}
	function importCSS($path) {
		if($GLOBALS["server"]) return '<link href="' .asset('css/' . $path) . '" rel="stylesheet">';
		return '<link href="' . $path . '" rel="stylesheet">';
	}
